#!/usr/bin/env bash
# SPDX-License-Identifier: AGPL-3.0-or-later
# SPDX-FileCopyrightText: 2026 Jonathan D.A. Jewell
#
# Generate rocq/CountsJuliaTable.v from the Agda table
# agda/src/MetaManifold/Evidence/CountsJuliaTable.agda, so the 169 Julia rows
# are never retyped by hand.  The Agda file is itself generated by
# julia/gen/emit_table.jl; this is a second, mechanical transcription.
#
# Usage: scripts/gen-rocq-table.sh [OUTPUT]   (default rocq/CountsJuliaTable.v)
#
# Fails loudly on any line inside the table it does not recognise, on a
# missing terminator, and on a row count other than 169 (= 13 x 13, the
# grid 12 that CountsCertificate checks).
set -euo pipefail
cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.."
export LC_ALL=C

src=agda/src/MetaManifold/Evidence/CountsJuliaTable.agda
out="${1:-rocq/CountsJuliaTable.v}"
test -f "$src" || { echo "ERROR: $src not found" >&2; exit 1; }

digest="$(sha256sum "$src" | cut -d' ' -f1)"
tmp="$(mktemp "${out}.XXXXXX")"
trap 'rm -f -- "$tmp"' EXIT

awk -v digest="$digest" -v srcname="$src" '
function fail(msg) { printf "ERROR: %s:%d: %s\n", srcname, NR, msg > "/dev/stderr"; bad = 1; exit 1 }
function nat(s) { return s ~ /^[0-9]+$/ }
BEGIN {
  state = 0; rows = 0
  print "(* SPDX-License-Identifier: AGPL-3.0-or-later *)"
  print "(* SPDX-FileCopyrightText: 2026 Jonathan D.A. Jewell *)"
  print ""
  print "(* GENERATED by scripts/gen-rocq-table.sh from"
  print "   " srcname
  print "   (sha256 " digest "),"
  print "   which julia/gen/emit_table.jl generates from"
  print "   MetaManifoldEvidence.count_verdict and MetaManifoldEvidence.fibre over"
  print "   reads, noise in 0..12.  Do not edit. *)"
  print ""
  print "From MetaManifoldEvidence Require Import ResidualEvidence CountsGrid."
  print "Import Row."
  print ""
  print "Definition expected : list Row :="
}
state == 0 && $0 == "expected : List Row" { state = 1; next }
state == 1 { if ($0 == "expected =") { state = 2; next } else fail("expected \"expected =\"") }
state == 2 {
  if ($0 == "  []") { state = 3; next }
  if (NF != 7 || $1 != "row" || !nat($2) || !nat($3) || !nat($5) || !nat($6) || $7 != "\342\210\267")
    fail("unrecognised table line: " $0)
  if ($4 != "entailed" && $4 != "refuted" && $4 != "unresolved" && $4 != "inconsistent")
    fail("unknown verdict: " $4)
  printf "  row %s %s %s %s %s ::\n", $2, $3, $4, $5, $6
  rows++
  next
}
state == 3 && NF > 0 { fail("text after the table terminator: " $0) }
END {
  if (bad) exit 1
  if (state != 3) { printf "ERROR: %s: table not found or not terminated\n", srcname > "/dev/stderr"; exit 1 }
  if (rows != 169) { printf "ERROR: %s: %d rows, expected 169\n", srcname, rows > "/dev/stderr"; exit 1 }
  print "  nil."
}
' "$src" > "$tmp"

mv -- "$tmp" "$out"
trap - EXIT
echo "wrote $out (169 rows from $src)"
